<template>
  <section class="bridge-edit-page">
    <div class="edit-heading"><div><span>桥梁档案</span><h2>{{ editing?'编辑桥梁基础状况':'新增桥梁基础状况' }}</h2></div><div><el-button @click="router.back()">取消</el-button><el-button type="primary" :loading="saving" @click="save"><Save :size="16"/>保存档案</el-button></div></div>
    <el-form label-position="top">
      <EditSection code="A" title="桥梁所处行政区划" subtitle="位置和坐标信息"><div class="form-grid"><Field v-for="item in areaFields" :key="item.key" :item="item"/></div></EditSection>
      <EditSection code="B" title="行政识别数据" subtitle="路线、桥梁身份及建设单位"><div class="form-grid"><el-form-item label="桥梁编号" required><el-input v-model="form.bridge_code" :disabled="editing"/></el-form-item><el-form-item label="桥梁名称" required><el-input v-model="form.bridge_name"/></el-form-item><el-form-item label="路线"><el-select v-model="form.route_code" filterable style="width:100%"><el-option v-for="item in routes" :key="item.route_code" :label="`${item.route_code} · ${item.route_name}`" :value="item.route_code"/></el-select></el-form-item><el-form-item label="桥梁类型"><el-select v-model="form.bridge_type_code" filterable style="width:100%"><el-option v-for="item in bridgeTypes" :key="item.bridge_type_code" :label="item.bridge_type_name" :value="item.bridge_type_code"/></el-select></el-form-item><Field v-for="item in identityFields" :key="item.key" :item="item"/></div></EditSection>
      <EditSection code="C" title="桥梁技术指标" subtitle="桥面、净空、引道和水文指标"><div class="form-grid"><Field v-for="item in technicalFields" :key="item.key" :item="item"/></div></EditSection>
      <EditSection code="D" title="桥梁结构信息" subtitle="数量决定表格列数，明细可逐行维护">
